import{_ as e,c as t,o as r,ah as E}from"./chunks/framework.BxT5r71R.js";const I=JSON.parse('{"title":"继BE：FIRST之后，MAZZEL之名寄托的“迷宫”与“热情”","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/1_继BE：FIRST之后，MAZZEL之名寄托的“迷宫”与“热情”.md","filePath":"zh-cn/Management2/PART2/1_继BE：FIRST之后，MAZZEL之名寄托的“迷宫”与“热情”.md"}'),n={name:"zh-cn/Management2/PART2/1_继BE：FIRST之后，MAZZEL之名寄托的“迷宫”与“热情”.md"};function o(T,a,i,S,p,s){return r(),t("div",null,[...a[0]||(a[0]=[E('<p>► 2022年11月</p><h2 id="继be-first之后-mazzel之名寄托的-迷宫-与-热情" tabindex="-1">继BE:FIRST之后，MAZZEL之名寄托的“迷宫”与“热情” <a class="header-anchor" href="#继be-first之后-mazzel之名寄托的-迷宫-与-热情" aria-label="Permalink to &quot;继BE:FIRST之后，MAZZEL之名寄托的“迷宫”与“热情”&quot;">​</a></h2><p>#新项目 #Mx2 #MAZZEL #不安 #烦恼 #决心 #幸福 #自有媒体</p><h3 id="人生在世-不安与烦恼总是相伴而来。每个人都希望获得幸福-而娱乐应当为这份心愿提供支持与启发。" tabindex="-1">“人生在世，不安与烦恼总是相伴而来。每个人都希望获得幸福，而娱乐应当为这份心愿提供支持与启发。” <a class="header-anchor" href="#人生在世-不安与烦恼总是相伴而来。每个人都希望获得幸福-而娱乐应当为这份心愿提供支持与启发。" aria-label="Permalink to &quot;“人生在世，不安与烦恼总是相伴而来。每个人都希望获得幸福，而娱乐应当为这份心愿提供支持与启发。”&quot;">​</a></h3><p><strong>2022年11月22日，BMSG在记者会上突然公布两项消息：与环球音乐（Universal Music）共同成立联合厂牌BE-U，以及继BE:FIRST之后推出第二支唱跳组合——MAZZEL。这是一支8人男子组合。为什么选择此时向公众介绍他们？他们又将成为怎样的组合？</strong></p><p>MAZZEL这个名字既取自意为“福音”“幸运”的“mazel”，又结合了“Maze”（迷宫）和“Zeal”（热情）两个词。正如他们出道前所经历的那样，人生就像一座“迷宫”，其间不乏烦恼与迷惘，但一定有“出口”。这个名字寄托了我们的决心：怀着热情走向“出口”，争取“幸福”，再将幸福传递给大家。</p><p>人生在世，不安与烦恼总是相伴而来。但每个人都希望获得幸福，而娱乐本就应当为这份心愿提供支持与启发。我认为，这种人所共有的处境与愿望，正是MAZZEL的主题。</p><h3 id="选择不同道路的ran与reiko" tabindex="-1">选择不同道路的RAN与REIKO <a class="header-anchor" href="#选择不同道路的ran与reiko" aria-label="Permalink to &quot;选择不同道路的RAN与REIKO&quot;">​</a></h3><p><strong>RAN和REIKO参加了选秀企划THE FIRST，BE:FIRST正是由此诞生的。此后，两人成为练习生（trainee），持续接受歌唱、舞蹈等各项训练。与此同时，他们还需要不断思考：“自己想做什么、想成为怎样的人？”最终，REIKO选择了MAZZEL之外的道路。</strong></p><p>两人都不是一开始就确定的新组合成员，而是与其他候选人站在同一起跑线上。RAN萌生了加入唱跳组合的愿望，但直到这次组建新组合，一路都不太顺利；REIKO则在逐渐建立起音乐人的自我意识后，尝试了各种可能性，最终选择了MAZZEL之外的道路。这个项目正是从两人的故事开始的。</p><p>在THE FIRST期间，如今BE:FIRST的成员虽然下定决心的时间各不相同，但我觉得，多数人当时都已认定，要把唱跳组合成员作为自己的人生道路。而当时的RAN和REIKO对此仍有些迷惘和烦恼，这主要是我从他们的表演中感受到的。</p><p>说得简单些，两人各自都有需要解决的问题。RAN不仅要下定决心加入唱跳组合，还需要通过表演等实践，进一步坚定朝着“自己希望成为怎样的艺人”这一方向前进的决心。REIKO参加THE FIRST时没有歌唱和舞蹈经验，通过这次选秀才开始深入接触音乐，因此必须不断思考：“自己真正应该做、想要做的究竟是什么？”所以，THE FIRST结束后，我一直着重观察两人的成长，以及他们的想法和发展方向如何变化，也和他们在幕后做了各种尝试。</p><p>至于REIKO经历了什么，最终选择了MAZZEL之外的道路，请大家看看将于2023年1月在YouTube频道开播的选秀纪录节目《MISSIONx2》（读作“Mission Mission”）。</p><h3 id="从新组合mazzel的命名中-也能感受到sky-hi自己所面对的-迷宫-。" tabindex="-1">从新组合MAZZEL的命名中，也能感受到SKY-HI自己所面对的“迷宫”。 <a class="header-anchor" href="#从新组合mazzel的命名中-也能感受到sky-hi自己所面对的-迷宫-。" aria-label="Permalink to &quot;从新组合MAZZEL的命名中，也能感受到SKY-HI自己所面对的“迷宫”。&quot;">​</a></h3><p>我想，每个人都有自己的人生故事。这个项目也会成为他们各自故事中的一步，帮助他们寻找“迷宫出口”。BMSG希望汇聚这样的伙伴：不满足于“什么也不想，放弃思考和行动，还试图把这种状态当作‘幸福’”，而是愿意追寻并获得真正的“幸福”。因此，我们格外重视他们寻找自己道路的过程。</p><p>我自己也同样身处迷宫。过去1年左右，组建MAZZEL这个项目始终伴随着各种难题。什么时候公布、公布什么、该如何推进，需要斟酌的事确实很多。其中最重要的一点，就是必须做出与BE:FIRST完全不同的东西。毕竟，BE:FIRST曾带给我极为强烈的成功体验。对我而言，需要找到的“迷宫出口”就在这里。</p><h3 id="尝试运用自有媒体" tabindex="-1">尝试运用自有媒体 <a class="header-anchor" href="#尝试运用自有媒体" aria-label="Permalink to &quot;尝试运用自有媒体&quot;">​</a></h3><p><strong>这次，BMSG特意选择通过自己的YouTube频道发布节目。在项目发布记者会上，SKY-HI也曾表示：“我就是想在YouTube上做。”</strong></p><p>原因有几个。我觉得，在传播渠道——也就是与观众接触的平台和媒体——中引入更多外部合作方，就像往咖啡里加牛奶。我们想确立并保留咖啡本身的味道，但加了牛奶，味道就多少有些不同。当然，首先要有知名度；要接触更广泛的大众，也确实需要拓展传播渠道，但要守住原本的味道，就得花很大功夫。不过，如果只通过BMSG自己的渠道发布，由核心团队来做，我想无论做什么，都会保留纯粹的BMSG特色。做THE FIRST时，公司刚成立不久，我把全部精力都投入其中，所以做出了自己满意的内容。但这一次，我需要一边处理BE:FIRST等各项工作，一边推进《MISSIONx2》。因此，我强烈地意识到一种风险：传播渠道增多后，项目或许还在推进，但BMSG想做、该做的事却打了折扣。另一方面，经过这2年的积累，BMSG已经形成了自己的特色，所以我觉得，我们有能力通过自有媒体来做，也很想这样做。至于为什么想做，是因为今后我们一定需要依托自家平台，建立强大的自有媒体传播能力。看到88rising（以美国为据点、向世界传播亚洲文化的厂牌，同时也是一家媒体）这样的例子，我更深切地感受到了这种必要性。与其只看眼前的成败，我想，现阶段或许更有必要先尝试一次。</p><p><strong>BE:FIRST从选秀到正式成团的过程，通过电视和网络几乎实时地呈现给观众。观众逐渐投入感情、产生期待，这也为组合在出道前赢得了粉丝。而这次则先公布出道成员，再展示组合诞生的历程，呈现顺序完全相反。</strong></p><p>对我来说，最基本的一点是，这个项目如果不做出与THE FIRST和BE:FIRST不同的东西，就没有意义。BE:FIRST本就是一群无法融入现有演艺体系、也无法在其中发挥才能的人聚在一起而诞生的。既然如此，如果我反过来又把THE FIRST的选秀机制或BE:FIRST的成员构成当作某种“模板”，那就是本末倒置，也是最危险的事。所以，方方面面都必须不同。</p><p>而且，做THE FIRST时，我全身心投入，集训期间还与参加者同吃同住。那段时间，我脑子里想的只有THE FIRST。这次，公司规模和状况都变了，我们也不会做完全相同的事。如果只是照搬当时的模板，做出来的无非是个更差的版本，或者说，我能预见的结果就只有失败。</p><p>那么，这次该怎么做？其实，早在项目初期，我就觉得先公布结果，再用纪录片讲述过程比较合适。成员最终确定之前的过程，我们也计划在YouTube上发布。希望大家看看，他们是如何走出最初那座“迷宫”的。我想，看过之后，大家或许就会明白，为什么这种形式最合适。这个项目的精髓，或者说其中一个高潮，我想从第一集就能感受到。</p><h3 id="创造与be-first截然不同的意义" tabindex="-1">创造与BE:FIRST截然不同的意义 <a class="header-anchor" href="#创造与be-first截然不同的意义" aria-label="Permalink to &quot;创造与BE:FIRST截然不同的意义&quot;">​</a></h3><p><strong>MAZZEL也是新厂牌BE-U推出的首支组合，该厂牌由BMSG与环球音乐共同成立。节目尚未上线，现阶段只能说“答案留待观看时揭晓”，但作为观众，我们可以期待些什么？</strong></p><p>MAZZEL这个项目从一开始，各方面的情况就与BE:FIRST不同。我当然也认为，只有方方面面都不同，这个项目才有意义，所以它应该也会朝着这个方向发展。我一直很担心，自己会受BE:FIRST成功经验的左右。试图照搬从选秀企划THE FIRST开始的成功之路，是非常危险的。但如果不是照搬，而是充分借助THE FIRST积累的发展势头，或将其中的逻辑运用到新项目中，推动新的成长，那么我觉得，目前的状况确实很好。我也强烈地感受到，MAZZEL或许能够创造出与BE:FIRST截然不同的意义、价值和成果。</p>',26)])])}const _=e(n,[["render",o]]);export{I as __pageData,_ as default};
